import { useEffect, useRef, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import {
  FileText, Download, RefreshCw, Shield, AlertTriangle,
  TrendingUp, CheckCircle2, Activity, Calendar, Printer,
  BarChart2, Globe, Bug, Lock, Database,
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useAudit } from "@/components/AuditLogViewer";

interface ReportData {
  generated_at: Date;
  period: string;
  totalThreats: number;
  criticalThreats: number;
  highThreats: number;
  mediumThreats: number;
  lowThreats: number;
  aiAnalyzed: number;
  topCategories: { name: string; count: number; pct: number }[];
  topSources: { name: string; count: number }[];
  recentCritical: { title: string; severity: string; source: string; date: string }[];
  riskScore: number;
  riskTrend: "increasing" | "stable" | "decreasing";
  keyFindings: string[];
  recommendations: string[];
}

async function generateReportData(days: number): Promise<ReportData> {
  const since = new Date(Date.now() - days * 24 * 3600 * 1000).toISOString();

  const [totals, criticalItems, sourceCounts, categoryCounts, aiCount] = await Promise.all([
    supabase.from("threat_items").select("severity", { count: "exact" }).gte("published_at", since),
    supabase.from("threat_items")
      .select("title,severity,source_name,published_at")
      .gte("published_at", since)
      .eq("severity", "critical")
      .order("published_at", { ascending: false })
      .limit(5),
    supabase.from("threat_items")
      .select("source_name")
      .gte("published_at", since)
      .limit(2000),
    supabase.from("threat_items")
      .select("category")
      .gte("published_at", since)
      .limit(2000),
    supabase.from("threat_items")
      .select("id", { count: "exact" })
      .gte("published_at", since)
      .not("ai_summary", "is", null),
  ]);

  const items = totals.data || [];
  const counts: Record<string, number> = { critical: 0, high: 0, medium: 0, low: 0 };
  items.forEach((i: any) => { if (counts[i.severity] !== undefined) counts[i.severity]++; });

  const srcMap: Record<string, number> = {};
  (sourceCounts.data || []).forEach((i: any) => { srcMap[i.source_name] = (srcMap[i.source_name] || 0) + 1; });
  const topSources = Object.entries(srcMap).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([name, count]) => ({ name, count }));

  const catMap: Record<string, number> = {};
  (categoryCounts.data || []).forEach((i: any) => { catMap[i.category] = (catMap[i.category] || 0) + 1; });
  const totalCat = Object.values(catMap).reduce((s, n) => s + n, 0) || 1;
  const topCategories = Object.entries(catMap).sort((a, b) => b[1] - a[1]).slice(0, 6).map(([name, count]) => ({ name, count, pct: Math.round((count / totalCat) * 100) }));

  const total = items.length;
  const riskScore = Math.min(Math.round((counts.critical * 40 + counts.high * 15 + counts.medium * 5) / Math.max(total, 1) * 10), 100);

  const keyFindings: string[] = [];
  if (counts.critical > 10) keyFindings.push(`${counts.critical} critical-severity threats detected — immediate response required`);
  if (counts.high > 50) keyFindings.push(`Elevated high-severity threat volume (${counts.high} items) — review triage process`);
  if (topCategories[0]) keyFindings.push(`"${topCategories[0].name}" is the dominant threat category (${topCategories[0].pct}% of feed)`);
  if (topSources[0]) keyFindings.push(`Most active intelligence source: ${topSources[0].name} (${topSources[0].count} items)`);
  if ((aiCount.count ?? 0) < total * 0.1) keyFindings.push("AI summary coverage is low — consider increasing Ollama processing capacity");

  const recommendations: string[] = [
    "Patch all CVEs with CVSS ≥ 9.0 within 24h of disclosure",
    "Enable DMARC/DKIM/SPF to mitigate phishing vector",
    "Review firewall rules for externally exposed management ports",
    "Enroll all privileged accounts in hardware MFA",
    counts.critical > 5 ? "Increase SOC monitoring hours during elevated threat periods" : "Maintain current SOC monitoring cadence",
  ];

  return {
    generated_at: new Date(),
    period: days === 7 ? "Last 7 days" : days === 30 ? "Last 30 days" : `Last ${days} days`,
    totalThreats: total,
    criticalThreats: counts.critical,
    highThreats: counts.high,
    mediumThreats: counts.medium,
    lowThreats: counts.low,
    aiAnalyzed: aiCount.count ?? 0,
    topCategories,
    topSources,
    recentCritical: (criticalItems.data || []).map((i: any) => ({
      title: i.title,
      severity: i.severity,
      source: i.source_name,
      date: new Date(i.published_at).toLocaleDateString(),
    })),
    riskScore,
    riskTrend: riskScore > 60 ? "increasing" : riskScore > 30 ? "stable" : "decreasing",
    keyFindings: keyFindings.length ? keyFindings : ["No significant anomalies detected in this reporting period"],
    recommendations,
  };
}

const riskLevel = (score: number) =>
  score >= 70 ? { label: "HIGH", color: "text-destructive" } :
  score >= 40 ? { label: "MEDIUM", color: "text-orange-400" } :
  { label: "LOW", color: "text-green-500" };

export default function ExecutiveReport() {
  const { toast } = useToast();
  const audit = useAudit();
  const [period, setPeriod] = useState(7);
  const [data, setData] = useState<ReportData | null>(null);
  const [loading, setLoading] = useState(false);
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => { generate(); }, []);

  const generate = async () => {
    setLoading(true);
    try {
      const d = await generateReportData(period);
      setData(d);
      audit.log("report.generate", "executive_report", undefined, { period });
    } catch (e: any) {
      toast({ title: "Report generation failed", description: e.message, variant: "destructive" });
    } finally {
      setLoading(false);
    }
  };

  const printReport = () => window.print();

  const downloadHTML = () => {
    if (!reportRef.current) return;
    const html = `<!DOCTYPE html><html><head><title>ThreatLens Executive Report</title><meta charset="utf-8">
<style>
  body { font-family: -apple-system, Arial, sans-serif; background: #030712; color: #e2e8f0; margin: 0; padding: 2rem; }
  h1,h2,h3 { color: #f8fafc; }
  .stat { display: inline-block; text-align: center; margin: 0 1rem; }
  .stat-val { font-size: 2.5rem; font-weight: 700; }
  .badge { padding: 2px 8px; border-radius: 999px; font-size: 11px; font-weight: 600; }
  .critical { color: #ef4444; } .high { color: #f97316; } .medium { color: #eab308; } .low { color: #22c55e; }
  table { width: 100%; border-collapse: collapse; margin: 1rem 0; }
  td, th { padding: 8px 12px; border: 1px solid #1e293b; text-align: left; font-size: 13px; }
  th { background: #0f172a; font-weight: 600; }
  li { margin: 6px 0; font-size: 14px; }
  .section { background: #0a0f1e; border: 1px solid #1e293b; border-radius: 8px; padding: 1.5rem; margin: 1.5rem 0; }
</style></head><body>
<h1>ThreatLens Executive Report</h1>
<p>Generated: ${data?.generated_at.toLocaleString()} · Period: ${data?.period}</p>
${reportRef.current.innerHTML}
</body></html>`;
    const blob = new Blob([html], { type: "text/html" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `threatlens-exec-report-${new Date().toISOString().split("T")[0]}.html`;
    a.click();
    audit.log("report.download", "executive_report", undefined, { period, filename: `threatlens-exec-report-${new Date().toISOString().split("T")[0]}.html` });
    toast({ title: "Report downloaded", description: `threatlens-exec-report-${new Date().toISOString().split("T")[0]}.html` });
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-5xl">
      {/* Page header (not printed) */}
      <div className="mb-6 flex items-start justify-between print:hidden">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <FileText className="h-6 w-6 text-primary" />
            <h1 className="text-3xl font-bold tracking-tight">Executive Report</h1>
          </div>
          <p className="text-muted-foreground">AI-powered threat intelligence summary for leadership briefings.</p>
        </div>
        <div className="flex items-center gap-2">
          <select
            value={period}
            onChange={e => setPeriod(Number(e.target.value))}
            className="h-9 rounded-lg border border-border bg-background px-3 text-sm focus:outline-none focus:ring-2 focus:ring-primary/40"
          >
            <option value={7}>Last 7 days</option>
            <option value={14}>Last 14 days</option>
            <option value={30}>Last 30 days</option>
            <option value={90}>Last 90 days</option>
          </select>
          <Button variant="outline" size="sm" onClick={generate} disabled={loading} className="gap-2">
            {loading ? <RefreshCw className="w-3.5 h-3.5 animate-spin" /> : <RefreshCw className="w-3.5 h-3.5" />}
            Refresh
          </Button>
          <Button variant="outline" size="sm" onClick={downloadHTML} disabled={!data} className="gap-2">
            <Download className="w-3.5 h-3.5" /> Export HTML
          </Button>
          <Button
            variant="outline"
            size="sm"
            disabled={!data}
            className="gap-2 border-purple-500/40 text-purple-400 hover:bg-purple-500/10"
            onClick={async () => {
              try {
                const { data: { session } } = await supabase.auth.getSession();
                const supabaseUrl = (supabase as any).supabaseUrl as string;
                const res = await fetch(
                  `${supabaseUrl}/functions/v1/stix-export?type=bundle&days=${period}`,
                  { headers: { "Authorization": `Bearer ${session?.access_token ?? ""}` } }
                );
                if (!res.ok) throw new Error("Export failed");
                const blob = await res.blob();
                const url  = URL.createObjectURL(blob);
                const a    = document.createElement("a");
                a.href     = url;
                a.download = `threatlens-stix-${new Date().toISOString().slice(0,10)}.json`;
                a.click();
                URL.revokeObjectURL(url);
              } catch (e: any) {
                toast({ title: "STIX export failed", description: e.message, variant: "destructive" });
              }
            }}
          >
            <Download className="w-3.5 h-3.5" /> STIX 2.1
          </Button>
          <Button variant="outline" size="sm" onClick={printReport} disabled={!data} className="gap-2">
            <Printer className="w-3.5 h-3.5" /> Print
          </Button>
        </div>
      </div>

      {loading && !data && (
        <div className="text-center py-16 text-muted-foreground">
          <RefreshCw className="w-8 h-8 mx-auto mb-4 animate-spin opacity-40" />
          <p>Generating executive report…</p>
        </div>
      )}

      {data && (
        <div ref={reportRef} className="space-y-6">
          {/* Report header */}
          <div className="rounded-2xl border border-border/60 bg-card/60 p-6">
            <div className="flex items-center justify-between mb-4">
              <div>
                <h2 className="text-xl font-bold">Cyber Threat Intelligence Report</h2>
                <p className="text-sm text-muted-foreground">
                  <Calendar className="inline w-3.5 h-3.5 mr-1" />
                  {data.period} · Generated {data.generated_at.toLocaleString()}
                </p>
              </div>
              <div className="text-right">
                <div className="text-xs text-muted-foreground mb-1">Overall Risk Level</div>
                <div className={`text-3xl font-bold ${riskLevel(data.riskScore).color}`}>
                  {riskLevel(data.riskScore).label}
                </div>
                <div className="text-xs text-muted-foreground">{data.riskScore}/100</div>
              </div>
            </div>
            <Progress value={data.riskScore} className="h-2" />
          </div>

          {/* Threat volume */}
          <Card className="border-border/60 bg-card/60">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm flex items-center gap-2">
                <Activity className="w-4 h-4 text-primary" />
                Threat Intelligence Volume
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-5 gap-4 text-center">
                {[
                  { label: "Total", value: data.totalThreats, cls: "text-foreground" },
                  { label: "Critical", value: data.criticalThreats, cls: "text-destructive" },
                  { label: "High", value: data.highThreats, cls: "text-orange-400" },
                  { label: "Medium", value: data.mediumThreats, cls: "text-yellow-500" },
                  { label: "AI Analyzed", value: data.aiAnalyzed, cls: "text-primary" },
                ].map(s => (
                  <div key={s.label}>
                    <div className={`text-3xl font-bold ${s.cls}`}>{s.value.toLocaleString()}</div>
                    <div className="text-xs text-muted-foreground mt-1">{s.label}</div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>

          {/* Key findings */}
          <Card className={`border ${data.criticalThreats > 0 ? "border-destructive/30 bg-destructive/5" : "border-border/60 bg-card/60"}`}>
            <CardHeader className="pb-3">
              <CardTitle className="text-sm flex items-center gap-2">
                <AlertTriangle className={`w-4 h-4 ${data.criticalThreats > 0 ? "text-destructive" : "text-primary"}`} />
                Key Findings
              </CardTitle>
            </CardHeader>
            <CardContent>
              <ul className="space-y-2">
                {data.keyFindings.map((f, i) => (
                  <li key={i} className="flex items-start gap-2 text-sm">
                    <span className="w-5 h-5 rounded-full bg-primary/15 text-primary text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{i + 1}</span>
                    {f}
                  </li>
                ))}
              </ul>
            </CardContent>
          </Card>

          <div className="grid md:grid-cols-2 gap-6">
            {/* Threat categories */}
            <Card className="border-border/60 bg-card/60">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm flex items-center gap-2">
                  <BarChart2 className="w-4 h-4 text-primary" />
                  Top Threat Categories
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-2.5">
                {data.topCategories.map(c => (
                  <div key={c.name} className="space-y-1">
                    <div className="flex items-center justify-between text-xs">
                      <span>{c.name}</span>
                      <span className="text-muted-foreground">{c.count} ({c.pct}%)</span>
                    </div>
                    <Progress value={c.pct} className="h-1.5" />
                  </div>
                ))}
              </CardContent>
            </Card>

            {/* Top sources */}
            <Card className="border-border/60 bg-card/60">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm flex items-center gap-2">
                  <Globe className="w-4 h-4 text-primary" />
                  Top Intelligence Sources
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-2">
                {data.topSources.map((s, i) => (
                  <div key={s.name} className="flex items-center gap-3 text-sm">
                    <span className="w-5 h-5 rounded-full bg-muted text-muted-foreground text-xs font-bold flex items-center justify-center shrink-0">{i + 1}</span>
                    <span className="flex-1 truncate">{s.name}</span>
                    <Badge variant="outline" className="text-[9px] shrink-0">{s.count} items</Badge>
                  </div>
                ))}
              </CardContent>
            </Card>
          </div>

          {/* Recent critical */}
          {data.recentCritical.length > 0 && (
            <Card className="border-destructive/30 bg-destructive/5">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm flex items-center gap-2 text-destructive">
                  <Shield className="w-4 h-4" />
                  Recent Critical Threats
                </CardTitle>
              </CardHeader>
              <CardContent>
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-border/60">
                      <th className="text-left py-2 pr-4 text-xs font-medium text-muted-foreground w-1/2">Threat</th>
                      <th className="text-left py-2 pr-4 text-xs font-medium text-muted-foreground">Source</th>
                      <th className="text-left py-2 text-xs font-medium text-muted-foreground">Date</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border/40">
                    {data.recentCritical.map((t, i) => (
                      <tr key={i}>
                        <td className="py-2.5 pr-4 text-xs leading-snug">{t.title}</td>
                        <td className="py-2.5 pr-4 text-xs text-muted-foreground">{t.source}</td>
                        <td className="py-2.5 text-xs text-muted-foreground">{t.date}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </CardContent>
            </Card>
          )}

          {/* Recommendations */}
          <Card className="border-border/60 bg-card/60">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm flex items-center gap-2">
                <CheckCircle2 className="w-4 h-4 text-green-500" />
                Recommended Actions
              </CardTitle>
            </CardHeader>
            <CardContent>
              <ol className="space-y-2">
                {data.recommendations.map((r, i) => (
                  <li key={i} className="flex items-start gap-3 text-sm">
                    <span className="w-6 h-6 rounded-full bg-green-500/15 text-green-500 text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{i + 1}</span>
                    <span>{r}</span>
                  </li>
                ))}
              </ol>
            </CardContent>
          </Card>

          {/* Footer */}
          <div className="text-center text-xs text-muted-foreground border-t border-border/60 pt-4">
            ThreatLens · Cyber Threat Intelligence Platform · {data.generated_at.toLocaleString()}
            <br />
            <span className="text-[10px]">This report is generated from live intelligence feeds and AI analysis. Verify critical findings before action.</span>
          </div>
        </div>
      )}
    </div>
  );
}
